-- cpd-migration: additive
-- A PR's description (commands.md §9.5a; pro-d93..pro-d96): nullable, because a PR that existed before this migration has
-- none, and `pr open` refuses it (`description_required`) until `cpd pr describe` stores one. Verbatim text, at most 65536
-- characters (non-empty after trimming is checked at the boundary). `prs_locked` is unchanged: the description is not a
-- Locked field. The history triggers of `prs` are regenerated by the runner's reconcile. The Event kind `pr-described`.
ALTER TABLE prs ADD COLUMN description TEXT CHECK (description IS NULL OR length(description) BETWEEN 1 AND 65536);
INSERT INTO event_kinds (name) VALUES ('pr-described');
